async def act(page):
    import io
    import csv

    # Use the knowledge-base helper to export the customers grid as CSV.
    # This helper will navigate to /index.php/admin/customer/ and trigger a CSV download,
    # returning a dict with keys 'filename' and 'csv'.
    result = await export_customers_csv_via_grid(page, filename='customers.csv')

    csv_text = result.get('csv', '')

    # Parse CSV defensively and locate the row containing the phone number 2137418080.
    def digits(s: str) -> str:
        return ''.join(c for c in (s or '') if c.isdigit())

    reader = csv.DictReader(io.StringIO(csv_text))

    # Determine best candidate column names for name/email if headers vary.
    header_lower = {h.lower(): h for h in reader.fieldnames or []}

    name_key = None
    email_key = None

    # Common expected headers: 'Name', 'Email', 'Telephone'
    if 'name' in header_lower:
        name_key = header_lower['name']
    else:
        # pick first header that contains 'name'
        for hl, orig in header_lower.items():
            if 'name' in hl:
                name_key = orig
                break

    if 'email' in header_lower:
        email_key = header_lower['email']
    else:
        for hl, orig in header_lower.items():
            if 'email' in hl:
                email_key = orig
                break

    # Search rows for the telephone value
    target_digits = '2137418080'
    found = None
    for row in reader:
        # Check every cell for the phone digits to be robust against header variations
        for v in row.values():
            if digits(v) == target_digits:
                # Found the matching row
                # Extract name and email using discovered keys or fallbacks
                name = None
                email = None
                if name_key:
                    name = row.get(name_key)
                else:
                    # fallback: find any column containing 'name' in header
                    for h in row:
                        if 'name' in h.lower():
                            name = row[h]
                            break
                if email_key:
                    email = row.get(email_key)
                else:
                    for h in row:
                        if 'email' in h.lower():
                            email = row[h]
                            break

                # As a last resort, try common positional fields
                if not name:
                    # try 'First Name' + 'Last Name' concatenation
                    first = None
                    last = None
                    for h in row:
                        hl = h.lower()
                        if 'first' in hl and 'name' in hl:
                            first = row[h]
                        if 'last' in hl and 'name' in hl:
                            last = row[h]
                    if first or last:
                        name = ' '.join(p for p in (first or '', last or '') if p).strip()

                # Normalize empty to empty string
                name = name or ''
                email = email or ''

                found = (name, email)
                break
        if found:
            break

    if found:
        # Print only the requested result: customer name and email separated by a comma and space.
        print(f"{found[0]}, {found[1]}")
    else:
        # If not found, print nothing or an explicit empty result (here we print nothing).
        print("")

